Pass `generate` to make real images. It gets the prompt, model and ratio with an AbortSignal and resolves to up to four image URLs; the first one resolves from blocks to sharp once it loads.

```tsx title="studio.tsx"
"use client";

import ImageGenerationCard from "@/components/kokonutui-pro/image-generation-card";

export function Studio() {
  return (
    <ImageGenerationCard
      generate={async (request, signal) => {
        const res = await fetch("/api/images", {
          method: "POST",
          body: JSON.stringify(request),
          signal,
        });
        if (!res.ok) {
          throw new Error("The model is busy, try again in a minute");
        }
        const { urls } = await res.json();
        return urls;
      }}
      models={["gpt-image-1"]}
    />
  );
}
```

